import React, { useState, useCallback, useEffect } from 'react';
import { AuthProvider, useAuth } from './context/AuthContext';
import { signOut, createBet, updateBet, getTipsters } from './utils/api';
import LoginPage  from './pages/LoginPage';
import Dashboard  from './pages/Dashboard';
import BetsList   from './pages/BetsList';
import Analysis   from './pages/Analysis';
import Tipsters   from './pages/Tipsters';
import Settings   from './pages/Settings';
import AdminPage  from './pages/AdminPage';
import BetModal   from './components/BetModal';
import { useToast } from './hooks/useToast';

function AppInner() {
  const { user, loading, isAdmin } = useAuth();
  const [page, setPage]         = useState('dashboard');
  const [modal, setModal]       = useState(false);
  const [editBet, setEditBet]   = useState(null);
  const [refreshKey, setRefresh]= useState(0);
  const [tipsters, setTipsters] = useState([]);
  const { toasts, toast }       = useToast();

  const refresh = useCallback(()=>setRefresh(k=>k+1),[]);

  useEffect(()=>{ if(user) getTipsters().then(setTipsters); },[user,refreshKey]);

  if (loading) return (
    <div style={{minHeight:'100vh',display:'flex',alignItems:'center',justifyContent:'center',background:'var(--bg)'}}>
      <div style={{color:'var(--text3)',fontSize:14}}>Carregando…</div>
    </div>
  );

  if (!user) return <LoginPage />;

  const openNew  = () => { setEditBet(null); setModal(true); };
  const openEdit = (b) => { setEditBet(b);   setModal(true); };
  const closeModal = () => { setModal(false); setEditBet(null); };

  const handleSave = async(data) => {
    if (editBet) { await updateBet(editBet.id,data); toast('Aposta atualizada! ✓','success'); }
    else         { await createBet(data);             toast('Aposta adicionada! ✓','success'); }
    closeModal(); refresh();
  };

  const handleSignOut = async () => { await signOut(); };

  const NAV = [
    { id:'dashboard', label:'Dashboard',  icon:'◼' },
    { id:'bets',      label:'Apostas',    icon:'≡' },
    { id:'analysis',  label:'Análise',    icon:'↗' },
    { id:'tipsters',  label:'Tipsters',   icon:'📋' },
    { id:'settings',  label:'Config',     icon:'⚙' },
    ...(isAdmin ? [{ id:'admin', label:'Admin', icon:'🛡' }] : []),
  ];

  return (
    <div style={{display:'flex',minHeight:'100vh'}}>
      {/* Sidebar */}
      <aside style={{width:212,background:'var(--accent)',display:'flex',flexDirection:'column',
        position:'fixed',top:0,left:0,bottom:0,zIndex:100}}>
        <div style={{padding:'20px 18px 16px',borderBottom:'1px solid rgba(255,255,255,.08)'}}>
          <div style={{fontSize:17,fontWeight:700,color:'#fff',letterSpacing:'-.3px'}}>📊 BetTracker</div>
          <div style={{fontSize:11,color:'rgba(255,255,255,.4)',marginTop:1}}>Pro v3.0</div>
        </div>

        {/* User info */}
        <div style={{padding:'10px 18px',borderBottom:'1px solid rgba(255,255,255,.08)'}}>
          <div style={{fontSize:11,color:'rgba(255,255,255,.4)',marginBottom:2}}>Logado como</div>
          <div style={{fontSize:12,color:'rgba(255,255,255,.8)',fontWeight:500,
            overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>
            {user.email}
          </div>
          {isAdmin&&<div style={{fontSize:10,color:'#ffd700',marginTop:2}}>🛡 Administrador</div>}
        </div>

        <nav style={{flex:1,padding:'10px 0'}}>
          {NAV.map(n=>(
            <button key={n.id} onClick={()=>setPage(n.id)} style={{
              display:'flex',alignItems:'center',gap:10,width:'100%',padding:'10px 18px',
              background:page===n.id?'rgba(255,255,255,.1)':'transparent',
              border:'none',borderLeft:`3px solid ${page===n.id?'#fff':'transparent'}`,
              color:page===n.id?'#fff':'rgba(255,255,255,.5)',
              fontSize:13,fontWeight:page===n.id?600:400,cursor:'pointer',
              fontFamily:'inherit',textAlign:'left',transition:'all .12s',
            }}>
              <span style={{fontSize:16,width:20,textAlign:'center'}}>{n.icon}</span>
              {n.label}
            </button>
          ))}
        </nav>

        <div style={{padding:'12px 18px',borderTop:'1px solid rgba(255,255,255,.08)',display:'flex',flexDirection:'column',gap:8}}>
          <button className="btn" onClick={openNew} style={{
            width:'100%',justifyContent:'center',
            background:'rgba(255,255,255,.12)',color:'#fff',border:'1px solid rgba(255,255,255,.2)',
          }}>+ Nova Aposta</button>
          <button className="btn" onClick={handleSignOut} style={{
            width:'100%',justifyContent:'center',
            background:'transparent',color:'rgba(255,255,255,.4)',border:'none',fontSize:12,
          }}>Sair</button>
        </div>
      </aside>

      {/* Main */}
      <div style={{marginLeft:212,flex:1}}>
        <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',
          padding:'16px 28px',borderBottom:'1px solid var(--border)',background:'var(--surface)',
          position:'sticky',top:0,zIndex:50}}>
          <div style={{fontSize:18,fontWeight:700}}>
            {NAV.find(n=>n.id===page)?.label}
          </div>
          <button className="btn btn-primary" onClick={openNew}>+ Nova Aposta</button>
        </div>

        <div style={{padding:'24px 28px'}}>
          {page==='dashboard' && <Dashboard refreshKey={refreshKey} onNewBet={openNew} />}
          {page==='bets'      && <BetsList  refreshKey={refreshKey} tipsters={tipsters} onEdit={openEdit} onRefresh={refresh} toast={toast} />}
          {page==='analysis'  && <Analysis  refreshKey={refreshKey} />}
          {page==='tipsters'  && <Tipsters  refreshKey={refreshKey} onTipstersChange={setTipsters} toast={toast} />}
          {page==='settings'  && <Settings  toast={toast} />}
          {page==='admin' && isAdmin && <AdminPage />}
          {page==='admin' && !isAdmin && <div style={{padding:40,color:'var(--red)'}}>Acesso negado.</div>}
        </div>
      </div>

      {modal&&<BetModal bet={editBet} tipsters={tipsters} onSave={handleSave} onClose={closeModal} />}

      <div style={{position:'fixed',bottom:20,right:20,zIndex:999,display:'flex',flexDirection:'column',gap:8}}>
        {toasts.map(t=>(
          <div key={t.id} style={{
            padding:'10px 16px',borderRadius:'var(--radius)',fontSize:13,fontWeight:500,
            minWidth:220,animation:'slideUp .2s',boxShadow:'var(--shadow)',
            background:t.type==='success'?'var(--green)':t.type==='error'?'var(--red)':'var(--text)',color:'#fff',
          }}>{t.message}</div>
        ))}
      </div>
    </div>
  );
}

export default function App() {
  return <AuthProvider><AppInner /></AuthProvider>;
}
